CREATE ROLE authenticated;CREATE ROLE anon;CREATE SCHEMA auth;CREATE TABLE auth.users(id uuid PRIMARY KEY,email text);CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;GRANT USAGE ON SCHEMA auth TO authenticated;
CREATE TABLE item_styles(id uuid primary key default gen_random_uuid(),job_card_no text,design_code text,style_no text,set_type text,import_key text,primary_image_url text,linked_job_card_id uuid,updated_at timestamptz);
CREATE TABLE item_variants(id uuid primary key default gen_random_uuid(),style_id uuid references item_styles(id) ON DELETE CASCADE,job_card_no text,colour text,colour_normalized text,style_no text,set_type text,variant_status text,match_level text,import_key text,import_source text,source_row_start int,source_row_end int,updated_at timestamptz);
CREATE TABLE item_detail_lines(id uuid primary key default gen_random_uuid(),variant_id uuid references item_variants(id) ON DELETE CASCADE,category text,material_name text,material_name_normalized text,quantity numeric,unit text,secondary_quantity numeric,secondary_unit text,notes text,source_text text,source_row int,review_status text,review_note text,import_key text);
CREATE TABLE item_compositions(id uuid primary key default gen_random_uuid(),style_id uuid references item_styles(id) ON DELETE CASCADE,component_name text,component_name_normalized text,qty_per_set int CHECK(qty_per_set>0),unit text,sort_order int,notes text,updated_at timestamptz);
CREATE TABLE job_cards(id uuid primary key default gen_random_uuid(),job_card_no text,style_en text,party_name text,total_pieces int,due_date date,stage text,design_code text);
CREATE TABLE production_batches(id uuid primary key default gen_random_uuid(),job_card_no text,style_name text);
CREATE TABLE stitching_entries(id uuid primary key default gen_random_uuid(),job_card_ref text,style_name text);
CREATE TABLE qc_entries(id uuid primary key default gen_random_uuid(),job_card_ref text,style_name text,entry_no text NOT NULL,date date NOT NULL,stitching_entry_ref text,total_pieces_received int,total_pass int,total_fail int,net_passed int,defect_categories text[],status text,remarks text,created_at timestamptz DEFAULT now());
CREATE TABLE finishing_stock(id uuid DEFAULT gen_random_uuid(),job_card_ref text,component text,size text,colour text,finished_qty int,stitch_receive_ref text,stitch_received_qty int,pending_qty int);
CREATE TABLE component_assembly_vouchers(id uuid PRIMARY KEY,voucher_no text UNIQUE,voucher_date date,job_card_ref text,job_card_id uuid,style_name text,party_name text,final_item_name text,colour text,size text,total_sets_assembled int,total_components_used int,remarks text,created_by text,updated_by text);
CREATE TABLE component_assembly_items(id uuid DEFAULT gen_random_uuid(),assembly_voucher_id uuid REFERENCES component_assembly_vouchers(id),component text,size text,colour text,available_finished_qty int,qty_used int);
CREATE TABLE finished_goods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_card_ref text,style_name text,party_name text,item text,colour text,size text,total_pieces int,available_for_dispatch int,dispatched_pieces int,source text,source_voucher_no text,source_voucher_id uuid,date_added date,status text,created_by text,updated_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE dispatch_vouchers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dispatch_no text NOT NULL,dispatch_date date NOT NULL,party_name text NOT NULL,job_card_ref text,style_name text,finished_goods_id uuid REFERENCES finished_goods(id),item_name text,colour text,size text,ordered_pieces integer,dispatched_pieces integer,vehicle_no text,driver_name text,invoice_no text,remarks text,status text,created_by text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE sales_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_date text NOT NULL,vch_no text NOT NULL,party_name text NOT NULL,party_type text,total_qty int,total_amount numeric,job_card_no text,status text,created_by text,updated_by text,created_at timestamptz DEFAULT now());
CREATE TABLE qc_sub_components(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),qc_entry_id uuid,component text,pass_count integer,pieces_received int,fail_count int,size_breakdown jsonb,defect_categories text[]);
CREATE TABLE contractor_receive_vouchers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voucher_no text,job_card_ref text,voucher_date date,contractor_name text,total_received int,remarks text,created_by text,updated_by text,updated_at timestamptz);
CREATE TABLE contractor_receive_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receive_voucher_id uuid,item text,size text,colour text,received_today int,issue_item_id uuid,issued_qty int,already_received int,balance_before int);
CREATE TABLE grey_fabric_purchases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_no text UNIQUE,balance_in_stock numeric(15,3));
CREATE TABLE printer_fabric_issues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),issue_no text,date date,printer_account text,gray_fabric_ref text,fabric_name text,qty_issued numeric(12,3),qty_received numeric(12,3) DEFAULT 0,qty_pending numeric(12,3) GENERATED ALWAYS AS(qty_issued-qty_received) STORED,status text,updated_by text);
CREATE TABLE printer_fabric_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receipt_no text,date date NOT NULL,printer_account text,issue_id uuid REFERENCES printer_fabric_issues(id),gray_fabric_ref text,fabric_name text,qty_received numeric(12,3),processed_fabric_name text,processed_qty numeric(12,3),shortage numeric(12,3),shrinkage numeric(12,3),remarks text,created_by text);
CREATE TABLE fabric_inventory(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fabric_name text,finished_fabric_name text,unit text,stock_qty numeric,category text,status text,inventory_stage text,source_module text,source_receipt_id text,source_grey_fabric_ref text,processor_name text,processing_type text,received_date date,created_by text,UNIQUE(source_module,source_receipt_id));
CREATE TABLE contractor_issue_vouchers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voucher_no text,job_card_ref text,contractor_name text);
CREATE TABLE contractor_issue_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),issue_voucher_id uuid,item text,size text,colour text,issued_qty int,received_qty int DEFAULT 0,balance_qty int,updated_at timestamptz);
CREATE TABLE emb_issue_vouchers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),process_type text,status text);
CREATE TABLE emb_receive_vouchers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),issue_voucher_id uuid);
CREATE TABLE stitch_audit_trail(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz DEFAULT now());
CREATE TABLE sales_order_items(id uuid primary key default gen_random_uuid(),item_name text,sales_order_id uuid REFERENCES sales_orders(id) ON DELETE CASCADE,param_size text,param_colour text,qty int,unit text,price numeric,amount numeric);
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
